import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count is the number of lines, not the sum of quantities', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 2);
  assert.equal(itemCount([]), 0);
});

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 500, qty: 2 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550);
});

test('nine lines get no bulk discount', () => {
  const lines = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8100);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});
